declare function registerEmailmdTools(server: McpServer, options?: McpServerOptions): void;
/** Create a ready-to-connect emailmd MCP server (used by `emailmd mcp`). */
declare function createEmailmdMcpServer(options?: McpServerOptions): McpServer;

